@if($type==='student-statistics')<table class="table table-vcenter"><thead><tr><th>Campus</th>@foreach($statistics['columns'] as $column)<th>{{ $column }}</th>@endforeach<th>Total</th></tr></thead><tbody>@foreach($statistics['rows'] as $row)<tr><th>{{ $row['campus'] }}</th>@foreach($row['cells'] as $cell)<td>{{ $cell }}</td>@endforeach<td>{{ $row['total'] }}</td></tr>@endforeach</tbody><tfoot><tr><th>Grand Total</th>@foreach($statistics['columnTotals'] as $total)<th>{{ $total }}</th>@endforeach<th>{{ $statistics['grandTotal'] }}</th></tr></tfoot></table>@else<table class="table table-vcenter reports-student-list-table"><thead><tr><th>#</th><th>Student ID</th><th>Student Name</th><th>Gender</th><th>Academic Year</th><th>Campus</th><th>Class</th><th>Group</th><th>Status</th></tr></thead><tbody>@forelse($enrollments as $index=>$row)<tr><td>{{ $index+1 }}</td><td>{{ $row->student?->student_id }}</td><td><div class="student-name-kh">{{ $row->student?->full_name_kh ?: '-' }}</div><div class="student-name-en">{{ $row->student?->full_name_en ?: '-' }}</div></td><td>{{ strtoupper(substr((string) $row->student?->gender, 0, 1)) === 'F' ? 'F' : 'M' }}</td><td>{{ $row->academicYear?->academic_year }}</td><td>{{ $row->campus?->campus_name_en }}</td><td>{{ ($row->grade?->grade ?? '') . ($row->schoolClass?->class_name ?? '') }}</td><td>{{ $row->session?->session_short_name ?: '-' }}</td><td>{{ $row->enrollment_status }}</td></tr>@empty<tr><td colspan="9" class="text-center text-secondary">No students found.</td></tr>@endforelse</tbody></table><style>.student-name-kh{line-height:1.35}.student-name-en{font-family:"Khmer OS Siemreap","Khmer OS Siem Reap",sans-serif;line-height:1.35}</style>@endif
